      "enum": [
        "build",
        "typecheck",
        "unit",
        "integration",
        "contract",
        "browser"
      ]
    },
    "nodeId": {
      "description": "A worker lane id: lower-case, at most 32 characters, never a fixed graph node (review, candidate, handoff, approval, integrate), a finding attribution (multiple, none, both) or a per-lane node prefix (launch_, verify_, candidate_, review-).",
      "type": "string",
      "pattern": "^(?!(?:review|candidate|handoff|approval|integrate|multiple|none|both)$)(?!(?:launch_|verify_|candidate_|review-))[a-z][a-z0-9-]{0,31}$"
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "version": {
            "const": "1.0.0"
          }
        }
      },
      "then": {
        "not": {
          "anyOf": [
            {
